using Nickelony.IDEKit.IntelliSense.Completion;
using System;
using System.Collections.Concurrent;
using System.Windows.Media;
using TombLib.Scripting.Lua.Resources;

namespace TombLib.Scripting.Lua.Completion;

// Geometry paths below are vendored from microsoft/vscode-codicons under the MIT license.
/// <summary>
/// Creates themed completion icons from the vendored Codicon geometry set.
/// </summary>
/// <remarks>
/// The icon cache is process-wide and immutable after creation: entries are frozen
/// <see cref="DrawingImage"/> instances keyed by theme name and completion kind. The cache is
/// owned by this factory and is safe to call from any thread (a concurrent dictionary keyed by
/// theme and kind plus a volatile theme-name guard). It is invalidated in place whenever the
/// active theme name changes, so entries stay bounded to the current theme and stale themed
/// brushes are never returned after a theme switch.
/// </remarks>
internal static class LuaCompletionIconFactory
{
	private static readonly ConcurrentDictionary<LuaCompletionIconCacheKey, ImageSource> Cache = new();

	private static volatile string? s_cachedThemeName;

	/// <summary>
	/// Gets the themed icon image for the supplied completion kind.
	/// </summary>
	/// <param name="kind">The shared completion kind.</param>
	/// <param name="brushSet">The brush set used to color the icon.</param>
	/// <returns>A cached frozen image for the requested icon.</returns>
	public static ImageSource GetIcon(TextCompletionItemKind kind, LuaThemeBrushSet brushSet)
	{
		// Icons are themed per active theme; when the theme changes, drop the stale entries so the
		// cache stays bounded to the currently active theme.
		if (!string.Equals(s_cachedThemeName, brushSet.ThemeName, StringComparison.Ordinal))
		{
			Cache.Clear();
			s_cachedThemeName = brushSet.ThemeName;
		}

		return Cache.GetOrAdd(new LuaCompletionIconCacheKey(brushSet.ThemeName, kind), _ => CreateIcon(kind, brushSet));
	}

	private readonly record struct LuaCompletionIconCacheKey(string ThemeName, TextCompletionItemKind Kind);

	private static DrawingImage CreateIcon(TextCompletionItemKind kind, LuaThemeBrushSet brushSet)
	{
		var drawingGroup = new DrawingGroup();

		foreach (string pathData in GetPathData(kind))
			drawingGroup.Children.Add(CreatePathDrawing(brushSet.GetCompletionItemBrush(kind), pathData));

		drawingGroup.Freeze();

		var image = new DrawingImage(drawingGroup);
		image.Freeze();
		return image;
	}

	private static GeometryDrawing CreatePathDrawing(Brush brush, string pathData)
	{
		Geometry geometry = Geometry.Parse(pathData);
		geometry.Freeze();
		return new GeometryDrawing(brush, null, geometry);
	}

